chapter(3, 'Guest requests on the phone', 'Follow a guest request from start to Done as the room attendant and log a found item.', 'Ravi (Housekeeper)', 'housekeeper', menu='Guests & Services', display='mobile')
step('Ravi opens Guests & Services. For him the module has one page, My guest requests.', 'Requests come to the phone of the person who must do them.', target='sel:main', auto=['click:menutop:Guests & Services'], action='click', expect='My guest requests opens.', check="ctx.page==='gsv-my-requests'")
read('The chips Open, Overdue, Done and All filter the list. A card shows the room, the request, the guest and the department, with Start and Complete.', 'Overdue requests are red, so the most urgent come first.', target='btn:Overdue', expect='The request cards.')
click('btn:Start', 'Tap Start on the first request.', 'Start stops the waiting time and starts the work time.', expect='The request is In progress.', msgText='Request started')
click('btn:Complete', 'Tap Complete.', 'Completing asks for a short note for the guest.', expect='A note box opens.', check="has('Mark done')")
step('Type the note: Delivered to the room. Tap Mark done.', 'The note is what the guest and the desk read later.', target='modalbtn:Mark done', auto=['type:field:Note for the guest|Delivered to the room', 'click:modalbtn:Mark done'], action='click', expect='The request is Done.')
click('btn:Found item', 'Tap Found item.', 'Anything found in a room is logged with the room and where it is kept.', expect='The Log a found item sheet opens.', check="has('Log item')")
step('Type the item Spectacles case and choose the room 105.', 'Reception returns found items from the register.', target='field:Item', auto=['type:field:Item|Spectacles case', 'select:field:Room|105'], action='type', expect='The item is described.')
click('modalbtn:Log item', 'Tap Log item.', 'The item is on the Lost & found list for reception.', expect='The found item is logged.')
click('btn:Done', 'Tap Done to see the finished requests.', 'Done lists what was completed, with the notes.', expect='The finished requests are listed.')
